}

.woocommerce-shipping-totals th {
    display: none !important;
}

.woocommerce-shipping-totals td {
    width: 100%;
    min-width: 100% !important;
    max-width: 100% !important;
}

.custom-shipping-heading h3,
h3.custom-payment-heading {
