/* ============================================================
   CHECKOUT - BETAALMETHODE
   ============================================================ */

h3.custom-payment-heading,
h3.checkout-payment-heading {
    margin-top: 20px !important;
}

ul.wc_payment_methods.payment_methods.methods {
    padding-top: 12px !important;
}

ul.wc_payment_methods.payment_methods.methods img {
    width: 32px !important;
    height: 32px !important;
    float: right !important;
}

.payment_methods li {
    background: #ffffff;
    padding: 17px 16px 11px 16px;
    border-bottom: 0;
    border-radius: 8px;
    margin-bottom: 9px !important;
}

.payment_box.payment_method_mollie_wc_gateway_ideal {
    display: none !important;
}

@media (max-width: 767px) {
    .e-checkout__order_review {
        padding: 0 !important;
        border: 0 !important;
    }

    div#payment {
        padding: 0 !important;
        border: 0 !important;
        margin-top: 16px !important;
    }
}

/* ============================================================
   CHECKOUT - RADIO & CHECKBOX STIJLEN
   ============================================================ */

.woocommerce-form__label-for-checkbox span {
    font-family: aptos, sans-serif !important;
}

/* De radio is een flex-item binnen het label. Zonder flex:0 0 auto en een
   expliciete min-width groeit hij mee met zijn eigen ::before en wordt het
   een ovaal. Het vinkje wordt absoluut gecentreerd in plaats van met padding
   geduwd, zodat het altijd midden in de cirkel staat. */
.woocommerce-checkout input[type="radio"][name^="shipping_method"],
.woocommerce-checkout input[type="radio"][name="payment_method"] {
    appearance: none;
    -webkit-appearance: none;
    flex: 0 0 auto;
    position: relative;
    display: inline-block;
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    padding: 0 !important;
    border: 1px solid #d8cfc7;
    border-radius: 50%;
    background: #fff;
    cursor: pointer;
    vertical-align: middle;
    margin: 0 12px 0 0 !important;
    transition: background 0.15s ease, border-color 0.15s ease;
}

.woocommerce-checkout input[type="radio"][name^="shipping_method"]:checked,
.woocommerce-checkout input[type="radio"][name="payment_method"]:checked {
    background: var(--e-global-color-accent);
    border-color: var(--e-global-color-accent);
}

.woocommerce-checkout input[type="radio"][name^="shipping_method"]:checked::before,
.woocommerce-checkout input[type="radio"][name="payment_method"]:checked::before {
    content: "";
    font-family: 'Font Awesome 5 Free';
    font-weight: 900;
    font-size: 9px;
    color: #fff;
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Labels waren accentkleurig en lazen als links */
#shipping_method li label,
.wc_payment_method label {
    color: #46211a;
}

/* Geselecteerde optie subtiel markeren */
#shipping_method li:has(input:checked),
.payment_methods li:has(input:checked) {
    box-shadow: inset 0 0 0 1px var(--e-global-color-accent);
}

/* Beschrijving onder een betaalmethode netjes inspringen */
.payment_box {
    margin: 10px 0 0 32px;
    padding: 0;
    background: transparent;
    font-size: 13px;
    line-height: 1.5;
}

.payment_box p {
    margin: 0;
}

/* ActiveCampaign marketing-checkbox */
#activecampaign_for_woocommerce_accepts_marketing_field .optional {
    display: none !important;
}

/* Ship to a different address */
.woocommerce-checkout #ship-to-different-address {
    display: flex;
    align-items: center;
    gap: 10px;
}

.woocommerce-checkout #ship-to-different-address label {
    cursor: pointer;
    margin: 0;
}

/* Create account */
.woocommerce-checkout .woocommerce-account-fields .woocommerce-form__label-for-checkbox {
    display: flex;
    align-items: center;
    gap: 10px;
}

.woocommerce-checkout .woocommerce-account-fields .woocommerce-form__label-for-checkbox span {
    cursor: pointer;
}

/* Alle checkboxes op de checkout in één keer.
   box-sizing en de absolute ::before zijn essentieel: zonder die twee rekt
   het vakje op tot de inhoud past en krijg je een ovaal van 34x26. */
.woocommerce-checkout #rememberme,
.woocommerce-checkout #ship-to-different-address-checkbox,
.woocommerce-checkout #createaccount,
input#activecampaign_for_woocommerce_accepts_marketing {
    appearance: none;
    -webkit-appearance: none;
    box-sizing: border-box;
    flex: 0 0 auto;
    position: relative;
    display: inline-block;
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    padding: 0 !important;
    border: 1px solid #d8cfc7;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
    vertical-align: middle;
    margin: 0 10px 0 0 !important;
    transition: background 0.15s ease, border-color 0.15s ease;
}

.woocommerce-checkout #rememberme:checked,
.woocommerce-checkout #ship-to-different-address-checkbox:checked,
.woocommerce-checkout #createaccount:checked,
input#activecampaign_for_woocommerce_accepts_marketing:checked {
    background: var(--e-global-color-accent);
    border-color: var(--e-global-color-accent);
}

.woocommerce-checkout #rememberme:checked::before,
.woocommerce-checkout #ship-to-different-address-checkbox:checked::before,
.woocommerce-checkout #createaccount:checked::before,
input#activecampaign_for_woocommerce_accepts_marketing:checked::before {
    content: "";
    font-family: 'Font Awesome 5 Free';
    font-weight: 900;
    font-size: 9px;
    color: #fff;
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ============================================================
