    width: 100%;
    padding: 16px;
    padding-left: 52px !important;
    padding-top: 12px !important;
    margin-bottom: 10px;
    border-radius: 8px;
    background: white !important;
    color: black !important;
    cursor: pointer;
}

#custom_terms_field label a {
    color: black !important;
    text-decoration: underline;
}

#custom_terms_field label:before {
    content: "";
    position: absolute;
    left: 20px;
    top: 14px;
    width: 19px;
    height: 19px;
    border: 1px solid #bbb;
    border-radius: 4px;
    background: #fff;
    margin-top: 5px;
}

#custom_terms_field input[type="checkbox"]:checked + span {
    position: relative;
}

#custom_terms_field input[type="checkbox"]:checked + span:after {
    content: "";
    position: absolute;
    left: -32px;
    top: 0;
    width: 21px;
    height: 21px;
