.woocommerce-checkout-review-order-table td,
.woocommerce-checkout-review-order-table th {
    display: block;
    flex: 1 1 auto;
}

.woocommerce-checkout-review-order-table .product-name,
.woocommerce-checkout-review-order-table th.product-name {
    flex: 1 1 70%;
}

.woocommerce-checkout-review-order-table .product-total,
.woocommerce-checkout-review-order-table th.product-total {
    flex: 0 0 auto;
    text-align: right;
    white-space: nowrap;
}

.woocommerce table.shop_table td {
    padding: 0 !important;
}

.elementor-widget-woocommerce-checkout-page .woocommerce .woocommerce-checkout-review-order-table .cart_item td {
    border: 0 !important;
}

.elementor-widget-woocommerce-checkout-page .woocommerce .woocommerce-checkout-review-order-table .cart_item td.product-name {
    max-width: 100% !important;
    display: flex;
    flex-wrap: wrap;
}

/* ============================================================
   ORDER REVIEW TABLE - PRODUCT RIJEN
   ============================================================ */

tr.cart_item {
    border: 1px solid #ebebeb !important;
    border-radius: 10px;
    padding: 16px !important;
    margin-bottom: 8px;
}

tr.cart-subtotal {
    display: none;
}

td.product-name {
    font-size: 15px !important;
    line-height: 19px !important;
    font-weight: bold !important;
}

.checkout-product-title {
    width: 100%;
}

/* dl.variation is toegevoegd: Super Forms schrijft item meta weg zonder de
   tc-epo-metadata klasse, waardoor deze opmaak er eerder niet op aangreep. */
dl.tc-epo-metadata.variation,
td.product-name dl.variation {
    width: 66%;
    margin-top: 14px;
    margin-left: 16px;
    font-weight: 400;
}

a.tm-cart-edit-options,
.tm-cart-edit-options {
    font-weight: 400 !important;
    font-style: normal !important;
    font-size: 12px !important;
    margin-top: 4px !important;
    order: 4;
    width: 100%;
}

.tc-associated-table-product-indent {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    padding-left: 0 !important;
    margin-top: -8px;
}

.tc-associated-table-product .tc-associated-table-product-price::after {
    display: none !important;
}

/* ============================================================
   ORDER REVIEW TABLE - PRODUCT AFBEELDING & QUANTITY BADGE
   ============================================================ */

.checkout-product-block {
    display: flex;
    flex-direction: row-reverse;
    justify-content: flex-end;
    margin-top: 8px;
}

.checkout-product-image-wrapper {
    z-index: 0 !important;
    margin-left: -18px;
}

.checkout-product-qty-wrapper {
    z-index: 100 !important;
    align-self: flex-end;
}

span.checkout-qty {
    max-width: 25px !important;
    max-height: 25px !important;
    min-width: 25px !important;
    min-height: 25px !important;
    background: var(--e-global-color-accent);
    color: white;
    border-radius: 50%;
    font-size: 14px;
    margin-top: -20px;
    margin-left: -6px;
    display: flex !important;
    align-items: center;
    justify-content: center;
}

/* ============================================================
   ORDER REVIEW TABLE - TOTAAL RIJEN
   ============================================================ */

tr.order-total {
    border-top: 1px solid #ebebeb !important;
    border-radius: 0;
    padding-top: 20px !important;
    margin-top: 35px !important;
}

.order-total th {
    font-size: 21px !important;
}

.order-total td {
    text-align: right;
}

.order-total bdi {
    font-size: 19px;
    font-weight: bold !important;
    display: block;
}

.order-total th,
.order-total td {
    padding: 0 !important;
    margin: 0 !important;
}
